package org.konaframework.grind

import org.konaframework.core.Application
import java.lang.reflect.InvocationTargetException
import java.lang.reflect.Modifier
import java.net.URLClassLoader
import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.Path
/**
 * Loads a compiled Kona application from its Gradle output directories and calls its bootstrap
 * `static Application create(String[] args)` (generated by `kona new` as `bootstrap.App`).
 *
 * App classes come from [root]'s `build/classes` (+ resources). Runtime dependencies
 * (Crema, Wire, Inertia, …) are resolved via the app's `konaClasspath` Gradle task when
 * available, so `grind serve --in-process` works for starter kits — not only the API skeleton.
 */
class AppLoader(
    private val root: Path,
    private val bootstrapClass: String = DEFAULT_BOOTSTRAP,
    private val runtimeClasspath: (Path) -> List<Path> = Companion::gradleRuntimeClasspath,
) {
    /** Loader of the app's classes, set by [create]; use it to load app classes by name. */
    var classLoader: ClassLoader? = null
        private set

    /** Per-boot staging directory for copied jars (null when only dirs / immutable jars). */
    private var stagedDirectory: Path? = null

    /**
     * Logical classpath (app outputs + runtime deps). Used for emptiness checks; [create]
     * materializes a Zip-safe copy via [ClasspathIsolation] before opening a ClassLoader.
     */
    fun classpath(): List<Path> {
        val outputs = outputDirs()
        if (outputs.isEmpty()) {
            return emptyList()
        }
        return outputs + runtimeClasspath(root)
    }

    fun create(args: Array<String>): Application {
        val logical = classpath()
        if (outputDirs().isEmpty()) {
            throw GrindException("No compiled classes under $root/build — run ./gradlew classes first")
        }
        close()
        val staged = ClasspathIsolation.materialize(root, logical)
        stagedDirectory = staged.directory
        val dirs = staged.entries
        val urls = dirs.map { it.toUri().toURL() }.toTypedArray()
        // Child-first for app types so soft reload does not keep stale build/classes from the
        // grind JVM classpath (./grind launches with full konaClasspath including app outputs).
        val loader = SoftReloadClassLoader(urls, AppLoader::class.java.classLoader)
        classLoader = loader
        // So Wire convention lookup / SPI discovery see app classes during boot and on this thread.
        Thread.currentThread().contextClassLoader = loader
        val clazz = try {
            Class.forName(bootstrapClass, true, loader)
        } catch (ex: ClassNotFoundException) {
            close()
            throw GrindException("Bootstrap class [$bootstrapClass] not found in $dirs")
        }
        val method = try {
            clazz.getMethod("create", Array<String>::class.java)
        } catch (ex: NoSuchMethodException) {
            close()
            throw GrindException("[$bootstrapClass] must declare static Application create(String[] args)")
        }
        if (!Modifier.isStatic(method.modifiers) || !Application::class.java.isAssignableFrom(method.returnType)) {
            close()
            throw GrindException(
                "[$bootstrapClass].create(String[]) must be static (@JvmStatic in Kotlin) and return Application",
            )
        }
        return try {
            val app = method.invoke(null, args) as Application
            discoverPackages(app, loader)
            app
        } catch (ex: InvocationTargetException) {
            close()
            throw ex.targetException
        }
    }

    /** Closes the child [URLClassLoader] so reloaded app classes can be collected. */
    fun close() {
        val loader = classLoader
        classLoader = null
        val staged = stagedDirectory
        stagedDirectory = null
        if (loader != null) {
            val current = Thread.currentThread()
            if (current.contextClassLoader === loader) {
                current.contextClassLoader = javaClass.classLoader
            }
            (loader as URLClassLoader).close()
        }
        ClasspathIsolation.deleteQuietly(staged)
    }

    /**
     * When `META-INF/kona/providers` is present on [loader], registers each listed
     * [org.konaframework.core.ServiceProvider] onto [app] (idempotent if already registered).
     */
    fun discoverPackages(app: Application, loader: ClassLoader): List<String> {
        if (PackageDiscovery.providerNames(loader).isEmpty()) {
            return emptyList()
        }
        return PackageDiscovery.registerAll(app, loader)
    }

    private fun outputDirs(): List<Path> =
        OUTPUT_DIRS.map { root.resolve(it) }.filter { Files.isDirectory(it) }

    companion object {
        const val DEFAULT_BOOTSTRAP = "bootstrap.App"

        private val OUTPUT_DIRS = listOf(
            "build/classes/kotlin/main",
            "build/classes/java/main",
            "build/resources/main",
        )

        /**
         * Runs `./gradlew -q konaClasspath` in [root] and splits the printed path list.
         * Returns empty when the wrapper or task is missing (API apps still work via parent CP).
         */
        /** Drop the cached konaClasspath printout so the next soft reload re-resolves paths. */
        fun invalidateClasspathCache(root: Path) {
            try {
                Files.deleteIfExists(root.resolve("build/kona-runtime.classpath"))
            } catch (_: Exception) {
                // Best-effort; a stale cache only slows composite-build freshness.
            }
        }

        fun gradleRuntimeClasspath(
            root: Path,
            starter: (Path, Path) -> Process? = Companion::startClasspathProcess,
        ): List<Path> {
            val cached = root.resolve("build/kona-runtime.classpath")
            if (Files.isRegularFile(cached)) {
                return parseClasspathFile(cached)
            }
            val wrapper = resolveGradleWrapper(root) ?: return emptyList()
            val process = starter(wrapper, root)
            if (process == null) {
                return emptyList()
            }
            process.waitFor()
            val output = process.inputStream.readAllBytes().toString(StandardCharsets.UTF_8)
            if (process.exitValue() != 0) {
                return emptyList()
            }
            val paths = parseClasspathLine(output)
            writeClasspathCache(cached, paths)
            return paths
        }

        internal fun startClasspathProcess(wrapper: Path, root: Path): Process? =
            try {
                ProcessBuilder(wrapper.toString(), "-q", "konaClasspath")
                    .directory(root.toFile())
                    .redirectErrorStream(true)
                    .start()
            } catch (_: Exception) {
                null
            }

        internal fun resolveGradleWrapper(root: Path): Path? {
            val unix = root.resolve("gradlew")
            if (Files.isRegularFile(unix)) {
                return unix
            }
            val windows = root.resolve("gradlew.bat")
            if (Files.isRegularFile(windows)) {
                return windows
            }
            return null
        }

        internal fun writeClasspathCache(cached: Path, paths: List<Path>) {
            if (paths.isEmpty()) {
                return
            }
            try {
                Files.createDirectories(cached.parent)
                Files.writeString(
                    cached,
                    paths.joinToString(java.io.File.pathSeparator) { it.toAbsolutePath().toString() },
                )
            } catch (_: Exception) {
                // cache is best-effort
            }
        }

        internal fun parseClasspathFile(file: Path): List<Path> =
            parseClasspathLine(Files.readString(file))

        internal fun parseClasspathLine(text: String): List<Path> {
            val line = text.lineSequence()
                .map { it.trim() }
                .lastOrNull {
                    it.contains(java.io.File.pathSeparator) ||
                        it.endsWith(".jar") ||
                        it.contains("classes")
                }
                ?: return emptyList()
            return line.split(java.io.File.pathSeparator)
                .map { it.trim() }
                .filter { it.isNotEmpty() }
                .map { Path.of(it) }
                .filter { Files.exists(it) }
        }
    }
}
